export type Severity = "critical" | "medium" | "normal" | "nodata";
export type Status = "New" | "Acknowledged" | "In Repair" | "Closed";

export type RootCause =
  | "Manufacturing defect"
  | "Wiring / connector fault"
  | "Soiling / dust"
  | "Shading / vegetation"
  | "Physical damage"
  | "Unknown"
  | null;

export interface Anomaly {
  id: string;
  panelId: string;
  row: number;
  col: number;
  type: string;
  deltaT: number | null;
  deltaTNorm: number | null;  // IEC 62446-3 normalised to 1000 W/m²
  severity: Severity;
  string: string;
  inverter: string;
  status: Status;
  rootCause: RootCause;
  date: string;
  inspectionTime: string;
  rgbNote: string;
  gps: { lat: number; lng: number };
  /** Actual panel outline surveyed from drone imagery (Block20_1GV_4.kml), [lng, lat] pairs, closed ring */
  footprint?: [number, number][];
  peakTemp?: number;
  refTemp?: number;
  irradiance?: number;
  moduleSerial?: string;
  dailyLossINR?: number;
  dailyLossKWh?: number;
}

